SELECT

FROM t_wx_member m


    m.deleted_flag = 0

        AND (
            m.nickname LIKE CONCAT('%', #{query.searchWord}, '%')
            OR m.invite_code = #{query.searchWord}
            OR CAST(m.member_id AS CHAR) = #{query.searchWord}
        )


        AND m.disabled_flag = #{query.disabledFlag}


        AND m.create_time >= #{query.beginDate}


        AND m.create_time < DATE_ADD(#{query.endDate}, INTERVAL 1 DAY)



    ORDER BY m.member_id DESC

SELECT

FROM t_wx_member m

WHERE m.deleted_flag = 0 AND m.member_id = #{memberId}

SELECT COUNT(*)
FROM t_helper_request
WHERE deleted_flag = 0 AND status = 0 AND to_member_id = #{memberId}
